type Number interface {
	int | int64 | float64
}

// SumBalances totals the values of a balance map.
func SumBalances[K comparable, V Number](m map[K]V) V {
	var total V
	for _, v := range m {
		total += v
	}
	return total
}

// Decode unmarshals JSON into a fresh T.
func Decode[T any](data []byte) T {
	var v T
	json.Unmarshal(data, &v)
	return v
}

// Usage today:
//   cfg := Decode[Config](raw)
//   limits := Decode[map[string]int64](raw)
